schema:
model RAJob (server/prisma/schema/ra-jobs.prisma), new optional columns, all additive:
  /// Score 0..1 of the deterministic title-to-role match (taxonomy/match.ts) that produced primaryTaxonomyId; null = never matched. SM-2.
  titleMatchScore Float?   @db.Real
  /// Canonical RASkill ids of the posting's skills, required first. SM-6.
  skillIds        String[] @default([])
  /// Lexical document (title, role labels en/zh/zhHant, canonical skill labels and aliases, summary, requirements head). CJK segmented in the application; Traditional folded to Simplified in this token copy only. Never displayed. SM-7.
  searchDoc       String?  @db.Text
  /// to_tsvector('simple', searchDoc), written by the application in the same statement as searchDoc. NOT a generated column (prisma db push cannot express one). SM-7.
  searchTsv       Unsupported("tsvector")?
  /// sha1 of the content a fit depends on: title + requirements text + skills. SM-5, SM-7.
  contentHash     String?
  /// Language of the posting text: 'en' | 'zh-Hans' | 'zh-Hant' | 'ja' | 'ko' | other BCP-47 primary tag. SM-7, SM-11.
  lang            String?
  /// { v: 1, contentHash, model, extractedAt, items: [{ id, kind: 'skill'|'experience'|'education'|'domain'|'scope', text (verbatim from the posting), importance: 'must'|'preferred' }] }. SM-8.
  requirements    Json?
  embedding       RAJobEmbedding?
  @@index([skillIds], type: Gin)
  @@index([searchTsv], type: Gin)   // if prisma validate asks for an operator class: searchTsv(ops: raw("tsvector_ops"))

model RAJobMatchScore (server/prisma/schema/ra-match.prisma), additive:
  /// RAJob content hash (title + requirements + skills) at score time; a changed posting makes the row stale. SM-5.
  jobContentHash String?
  /// 'fit_v3' | 'fit_v4': the rubric the stored components follow. SM-5, SM-8.
  rubricVersion  String?

model RAUserAffinity (server/prisma/schema/ra-feed.prisma), additive:
  /// { normalizedTitleKey: -1..0 } negative weights from "Not interested: wrong title". SM-12.
  titleWeights Json @default("{}")

model RATailorSession (server/prisma/schema/ra-resume.prisma), additive:
  /// { before: FitSnapshot | null, after: FitSnapshot | null } with FitSnapshot = { score, tier, kind, rubric, estimator, model, scoredAt } (strategy 2.2 I6). SM-5.
  fitSnapshot Json?
